<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-alt: #f8fafc;
        --text: #132238;
        --muted: #52627a;
        --border: #c9d3e1;
        --border-strong: #8aa0bd;
        --accent: #2563eb;
        --accent-strong: #1d4ed8;
        --shadow: 0 18px 40px -24px #1322384d;
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        color: var(--text);
        background: linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface);
        color: var(--text);
        transform: translateY(-200%);
        transition: transform 0.2s ease;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid var(--accent);
        outline-offset: 2px;
      }

      main {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 4rem 1.25rem;
      }

      .page-shell {
        width: min(100%, 36rem);
      }

      .card {
        background: var(--surface);
        border: 1px solid color-mix(in srgb, var(--border) 78%, white);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 2.25rem);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(1.6rem, 3vw, 2.2rem);
        line-height: 1.15;
        letter-spacing: -0.02em;
      }

      .subtitle {
        margin: 0 0 1.5rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        border: 1px solid var(--border);
        border-radius: 16px;
        background: var(--surface-alt);
        padding: 1rem;
      }

      .form-field legend {
        padding: 0;
        font-weight: 700;
        font-size: 1.05rem;
      }

      .required {
        color: var(--accent-strong);
        font-weight: 700;
      }

      .help-text {
        margin: 0.5rem 0 1rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .options {
        display: grid;
        gap: 0.75rem;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 0.75rem;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: 14px;
        background: var(--surface);
        cursor: pointer;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      .radio-option:hover {
        border-color: var(--border-strong);
      }

      .radio-option:has(input:focus-visible) {
        border-color: var(--accent);
        box-shadow: 0 0 0 3px #2563eb26;
      }

      .radio-option input {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0;
        accent-color: var(--accent);
        flex: none;
      }

      .radio-option span {
        font-weight: 600;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
      }

      button[type="submit"] {
        border: 0;
        border-radius: 999px;
        padding: 0.85rem 1.2rem;
        background: linear-gradient(180deg, var(--accent), var(--accent-strong));
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 14px 24px -18px #1d4ed8;
      }

      button[type="submit"]:hover {
        filter: brightness(1.03);
      }

      button[type="submit"]:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        font-size: 0.95rem;
      }

      .status.is-error {
        color: #b42318;
      }

      .status.is-success {
        color: #166534;
      }

      @media (max-width: 480px) {
        main {
          padding: 3rem 1rem;
        }

        .actions {
          justify-content: stretch;
        }

        button[type="submit"] {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        .skip-link,
        .card,
        .form-field,
        .radio-option,
        button[type="submit"] {
          forced-color-adjust: auto;
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .skip-link:focus,
        .radio-option:has(input:focus-visible),
        button[type="submit"]:focus-visible {
          outline: 2px solid Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="page-shell">
        <div class="card">
          <h1>Notification Preferences</h1>
          <p class="subtitle">Choose one way you would like to receive product updates.</p>

          <form id="notification-form" novalidate>
            <div class="form-field">
              <fieldset>
                <legend>How do you prefer to receive notifications? <span class="required">*</span></legend>
                <p class="help-text" id="notification-help">Select one option before submitting.</p>
                <div class="options" role="radiogroup" aria-describedby="notification-help notification-status">
                  <label class="radio-option" for="notification-email">
                    <input type="radio" id="notification-email" name="notification-method" value="Email" required />
                    <span>Email</span>
                  </label>
                  <label class="radio-option" for="notification-sms">
                    <input type="radio" id="notification-sms" name="notification-method" value="SMS" />
                    <span>SMS</span>
                  </label>
                  <label class="radio-option" for="notification-push">
                    <input type="radio" id="notification-push" name="notification-method" value="Push Notifications" />
                    <span>Push Notifications</span>
                  </label>
                </div>
              </fieldset>
            </div>

            <p id="notification-status" class="status" aria-live="polite"></p>

            <div class="actions">
              <button type="submit">Submit</button>
            </div>
          </form>
        </div>
      </section>
    </main>

    <script>
      (() => {
        const form = document.getElementById('notification-form');
        const status = document.getElementById('notification-status');
        const radios = Array.from(form.elements.namedItem('notification-method'));

        const setStatus = (message, type) => {
          status.textContent = message;
          status.className = `status ${type}`;
        };

        form.addEventListener('submit', (event) => {
          event.preventDefault();

          const selected = radios.find((radio) => radio.checked);

          if (!selected) {
            setStatus('Please choose one notification method before continuing.', 'is-error');
            radios[0].focus();
            return;
          }

          setStatus(`You selected ${selected.value}.`, 'is-success');
        });

        radios.forEach((radio) => {
          radio.addEventListener('change', () => {
            status.textContent = '';
            status.className = 'status';
          });
        });
      })();
    </script>
  </body>
</html>
